#include <stddef.h>
#include <stdint.h>

/* the layout of include/qemu/queue.h, QEMU 11.1 */
typedef struct QTailQLink {
    void *tql_next;
    struct QTailQLink *tql_prev;
} QTailQLink;

struct Job {
    int id;
    union {
        struct Job *tqe_next;
        QTailQLink tqe_circ;
    } entry;
};

union JobQ {
    struct Job *tqh_first;
    QTailQLink tqh_circ;
};

/* container_of(ptr, type, member): from a pointer to the member field of a struct type return a pointer to the struct itself.
   As in include/qemu/compiler.h: with a type check through typeof and offsetof. */
#define container_of(ptr, type, member) (0)

